), resolved AS (
  SELECT c.id AS category_id, i.*
  FROM incoming AS i
  JOIN public.categories AS c ON c.slug = i.category_slug
), updated AS (
  UPDATE public.questions AS q
  SET
    category_id = r.category_id,
    difficulty = r.difficulty,
    type = r.type,
    stimulus = r.stimulus,
    question = r.question,
    prompt = r.prompt,
    options = r.options::jsonb,
    correct_answer = r.correct_answer,
    explanation = r.explanation,
    status = r.status,
    content_metadata = r.content_metadata::jsonb,
    batch_id = r.batch_id,
    batch_metadata = r.batch_metadata::jsonb
  FROM resolved AS r
  WHERE q.content_hash = r.content_hash
  RETURNING q.content_hash
)
INSERT INTO public.questions (category_id, difficulty, type, stimulus, question, prompt, options, correct_answer, explanation, status, content_metadata, content_hash, batch_id, batch_metadata)
SELECT r.category_id, r.difficulty, r.type, r.stimulus, r.question, r.prompt, r.options::jsonb, r.correct_answer, r.explanation, r.status, r.content_metadata::jsonb, r.content_hash, r.batch_id, r.batch_metadata::jsonb
FROM resolved AS r
WHERE NOT EXISTS (SELECT 1 FROM public.questions AS q WHERE q.content_hash = r.content_hash);
